center=function(kind){if(kind==='promotions'){const rows=own().flatMap(k=>k.promotions.map(r=>({...r,k}))).filter(r=>[r.k.name,r.title,r.platform,r.remarks].join(' ').toLowerCase().includes(query.toLowerCase()));return `<section class="panel"><div class="toolbar"><label class="searchfield">${I('search')}<input id="search" value="${esc(query)}" aria-label="搜索合作案例" placeholder="搜索达人、标题、平台或备注"></label><button class="btn primary" data-addentry="promotions">添加案例</button></div>${caseTable(rows)}</section>`}if(kind!=='contracts')return v8Center(kind);const all=own().flatMap(k=>k.contracts.map(r=>({...r,k}))).filter(r=>(!contractMarket||r.k.market===contractMarket)&&[r.k.name,r.title].join(' ').toLowerCase().includes(query.toLowerCase())),rows=all.filter(r=>!contractFilter||contractCategory(r)===contractFilter);return `<section class="panel"><div class="toolbar"><label class="searchfield">${I('search')}<input id="search" value="${esc(query)}" aria-label="搜索签约记录" placeholder="搜索达人或合约标题"></label><select id="contractmarket" aria-label="签约市场"><option value="">全部市场</option>${C.unique(own().map(k=>k.market)).map(m=>`<option ${m===contractMarket?'selected':''}>${esc(m)}</option>`).join('')}</select><button class="btn primary" data-addentry="contracts">登记合约</button></div><div class="tabs">${[['','全部'],['已完成','已完成'],['等待乙方签约','等待乙方签约'],['合约编辑中','合约编辑中'],['待确认','历史待确认']].map(([v,l])=>`<button class="tab ${v===contractFilter?'active':''}" data-contractfilter="${v}">${l} <small>${all.filter(r=>!v||contractCategory(r)===v).length}</small></button>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>达人</th><th>合约</th><th>市场</th><th>分类</th><th>日期</th><th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="textbtn" data-open="${r.k.id}">${esc(r.k.name)}</button></td><td><strong>${esc(r.title)}</strong><small>${linkHTML(r.url,'查看合约')}</small></td><td>${show(r.k.market)}</td><td>${esc(contractCategory(r))}</td><td>${show(r.date)}</td><td><button class="btn small" data-editentry="${r.k.id}|contracts|${esc(r.id)}">编辑</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">暂无对应合约</div>'}</div><div class="footer">共 ${rows.length} 条 · 本机登记，不代表外部签约系统状态</div></section>`};
function caseEditorControl(field,label,old){const raw=old[field]??'';return ['remarks','promotionInfo'].includes(field)?`<div class="field"><label for="case-${field}">${label}</label><textarea id="case-${field}" rows="3" maxlength="2000">${esc(raw)}</textarea></div>`:inputField('case-'+field,label,raw,['views','likes','comments','clicks','shares','orders','revenue'].includes(field)?'number':field==='proof'?'url':'text')}
function caseEditorSnapshot(form,old){const fields=new Map();for(const [field,id] of [['title','entrytitle'],['url','entryurl'],['platform','entryplatform'],['date','entrydate'],['time','entrytime'],...caseLabels.map(([field])=>[field,'case-'+field]),['revenueCurrency','case-revenueCurrency']]){const input=form.querySelector('#'+id);if(input)fields.set(field,{input,display:input.value,raw:old[field]??''})}return fields}
function caseEditorOriginalLink(form,old,rid){const input=form.querySelector('#publicationfee');let changed=false;if(!rid||!input)return ()=>false;const original=old.feeId?old.feeId+'|'+(old.deliveryId??''):'';const restore=()=>{if(changed)return;if(!original){input.value='';return}if(![...input.options].some(option=>option.value===original)){const option=document.createElement('option');option.value=original;option.textContent='保留原关联（历史记录）';input.append(option)}input.value=original};restore();input.addEventListener('change',()=>{changed=true});for(const id of ['entrykol','entryplatform'])form.querySelector('#'+id)?.addEventListener('change',restore);return ()=>!changed}
const v8Entry=entryDialog;entryDialog=function(kind,kid,rid,context){guardProfileLeave(()=>{v8Entry(kind,kid,rid,context);const form=document.querySelector('#v4form');if(!form)return;if(kind==='contracts'){const el=document.querySelector('#entrystatus'),r=own().find(k=>k.id===kid)?.contracts.find(r=>r.id===rid);if(el)el.innerHTML=[...(r?.status==='待签约'?['待签约']:[]),'合约编辑中','等待乙方签约','已签约'].map(v=>`<option value="${v}" ${v===r?.status?'selected':''}>${v==='待签约'?'历史待确认':v==='已签约'?'已完成（登记已签约）':v}</option>`).join('');return}if(kind!=='promotions')return;const old=own().find(k=>k.id===kid)?.promotions.find(r=>r.id===rid)||{};form.querySelector('.actions').insertAdjacentHTML('beforebegin',`<details class="caseeditor"><summary>案例明细与统计（人工登记，可留空）</summary><div class="fieldgrid">${caseLabels.filter(([f])=>!['url','platform','date','customer','bd','attribute','email'].includes(f)).map(([f,l])=>caseEditorControl(f,l,old)).join('')}${inputField('case-revenueCurrency','收益币种',old.revenueCurrency??'')}</div></details>`);const originalFields=caseEditorSnapshot(form,old),originalLink=caseEditorOriginalLink(form,old,rid);const submit=form.onsubmit;form.onsubmit=async e=>{const saved=commit;commit=async n=>{const r=rid?n.kols.find(k=>k.id===Number(value('entrykol')))?.promotions.find(r=>r.id===rid):n.kols.find(k=>k.id===Number(value('entrykol')))?.promotions.at(-1);if(r){for(const [f,field] of originalFields)r[f]=rid&&field.input.value===field.display?field.raw:['remarks','promotionInfo'].includes(f)?field.input.value:field.input.value.trim();if(originalLink())for(const f of ['feeId','deliveryId','linkChoice'])r[f]=old[f]??''}return saved(n)};try{await submit(e)}finally{commit=saved}}})};
